WEAVE_SPEED = 13.89
LANE_WIDTH = 3.5  # 물리 차로 폭 가정. 차량 표시 배율은 mdp_config에서 독립 조절.
H = BRIDGE_HEIGHT

def curve(*segments, samples=32):
    """각 segment의 4개 제어점으로 3D cubic Bezier 표본화."""
    result = []
    for segment in segments:
        for i in range(samples + 1):
            if result and i == 0:
                continue
            t = i / samples
            weights = ((1-t)**3, 3*(1-t)**2*t, 3*(1-t)*t*t, t**3)
            result.append(tuple(sum(w*p[d] for w, p in zip(weights, segment))
                                for d in range(3)))
    return result



